  const s=String(raw||'').replace(/\s+/g,'').replace(/[.,]+$/,'');
  if(!/\d/.test(s))return'';
  const dec=s.match(/[.,](\d{2})$/);
  const inteiro=(dec?s.slice(0,-3):s).replace(/[.,]/g,'');
  if(!inteiro)return'';
