// Uso real do modelo (Análise Jurídica = Anthropic claude-sonnet-4-6) para telemetria de margem.
const _an = $('Análise Jurídica').first().json || {};
const _u = _an.usage || {};
const _inTok = (Number(_u.input_tokens) || 0) + (Number(_u.cache_read_input_tokens) || 0) + (Number(_u.cache_creation_input_tokens) || 0);
const _outTok = Number(_u.output_tokens) || 0;
// Preços claude-sonnet-4-6: US$3/1M input, US$15/1M output
const _costUsd = Number(((_inTok * 3 + _outTok * 15) / 1e6).toFixed(6));
const usage = { models: [{ workflow: 'lidimus-Juridico', model: 'claude-sonnet-4-6', promptTokens: _inTok, completionTokens: _outTok, totalTokens: _inTok + _outTok, costUsd: _costUsd }] };
try { const _em = $('Embeddings Consultas').first().json || {}; const _eu = _em.usage || {}; const _etot = Number(_eu.total_tokens) || Number(_eu.prompt_tokens) || 0; if (_etot) usage.models.push({ workflow: 'lidimus-Juridico', model: 'mistral-embed', promptTokens: Number(_eu.prompt_tokens) || 0, completionTokens: 0, totalTokens: _etot, costUsd: Number((_etot * 0.1 / 1e6).toFixed(6)) }); } catch (e) {}
// Estimativa do custo da Extração de Campos (mistral-medium; nó langchain não expõe usage real).
try { const _ocrLen = String($('Preparar Input').first().json.texto_ocr || '').length; const _mlIn = Math.round(_ocrLen / 4); const _mlOut = 400; if (_mlIn) usage.models.push({ workflow: 'lidimus-Juridico', model: 'mistral-medium-latest', promptTokens: _mlIn, completionTokens: _mlOut, totalTokens: _mlIn + _mlOut, costUsd: Number(((_mlIn * 0.4 + _mlOut * 2) / 1e6).toFixed(6)), estimated: true }); } catch (e) {}
return [{ json: { jobId: $('Preparar Input').first().json.jobId, stage: 'juridico', result, usage } }];

// ─── MONTAR ERRO ──────────────────────────────────────────────────────
// Ponto único de saída para qualquer falha do caminho principal. Todo nó que
// pode quebrar tem a saída de erro ligada aqui, e não porque erro seja raro:
// sem isso a execução morre calada. O "Responder Webhook" já devolveu
// "processing" no terceiro nó, então o Lidimus considera o disparo bem-sucedido
// e fica esperando um callback que nunca vem — até o watchdog varrer o job em
// 60 minutos. Foi o que aconteceu na execução 829: cinco minutos de falha,
// uma hora de ampulheta na tela do cliente.
const item = $input.first().json || {};

// Qual nó quebrou. $prevNode é quem entregou o item nesta execução, e só a
// saída de erro chega aqui — logo, é sempre o nó que falhou.
let noQueFalhou = '';
try { noQueFalhou = $prevNode.name || ''; } catch (e) {}

// O n8n põe a falha em `error` (ora string, ora objeto); nó HTTP às vezes
// devolve `message` no próprio item.
const bruto = (item.error && typeof item.error === 'object')
  ? (item.error.message || item.error.description || JSON.stringify(item.error))
  : (item.error || item.message || 'Falha na análise jurídica');

// O nó HTTP embrulha a resposta da API em "... Status 403\nBody: {json}".
// O que interessa a quem lê o laudo é a frase de dentro, não o envelope.
function desembrulhar(txt) {
  const m = String(txt).match(/Body:\s*(\{[\s\S]*\})\s*$/);
  if (!m) return String(txt);
  try {
    const b = JSON.parse(m[1]);
    const dentro = b.message || (b.error && (b.error.message || b.error)) || null;
    return dentro ? String(dentro) : String(txt);
  } catch (e) { return String(txt); }
}

const detalhe = desembrulhar(bruto).replace(/\s+/g, ' ').trim();
const onde = noQueFalhou ? ' (' + noQueFalhou + ')' : '';
// A execução vai junto: é por ela que o suporte acha o run no n8n sem ter de
// adivinhar pelo horário.
let execucao = '';
try { execucao = ' [execução ' + $execution.id + ']'; } catch (e) {}

const errorMessage = ('Falha na análise jurídica' + onde + ': ' + detalhe + execucao).slice(0, 500);
return [{ json: { errorMessage } }];

