let hits = [];
try {
  const resp = $input.first().json || {};
  for (const grupo of (resp.result || [])) { for (const h of (grupo || [])) { if (h && h.payload) hits.push(h); } }
} catch (e) {}
const porId = new Map();
for (const h of hits) { const k = String(h.id); if (!porId.has(k) || porId.get(k).score < h.score) porId.set(k, h); }
const top = [...porId.values()].sort((a, b) => b.score - a.score).slice(0, 8);
let fundamentos_rag = '';
if (top.length) {
  let total = 0; const partes = [];
  // Os trechos entram numerados e SEM capítulo/seção/score. Mandar o rótulo
  // interno junto convidava a IA a citá-lo, e o parecer saía com "Manual Prático
  // RI, Cap. 16, Anti-patterns" no corpo do texto jurídico.
  top.forEach((h, i) => {
    const p = h.payload; const texto = String(p.texto || '');
    if (total + texto.length > 12000) return;
    total += texto.length;
    const refs = (p.artigos_citados || []).slice(0, 8).join('; ');
    partes.push('[' + (i + 1) + ']\n' + texto + (refs ? '\nReferências citadas: ' + refs : ''));
  });
  if (partes.length) {
    fundamentos_rag = '=== APOIO DOUTRINÁRIO (uso interno) ===\n'
